import { useState } from 'react';
import { Button, Card, Input, Stack, Stepper, Text } from '@jinx-ui/react';

type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationFormProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_VALUES: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_ROWS: ReadonlyArray<[keyof RegistrationValues, string]> = [
  ['name', 'Имя'],
  ['email', 'E-mail'],
  ['phone', 'Телефон'],
  ['country', 'Страна'],
  ['city', 'Город'],
  ['street', 'Улица, дом'],
  ['zip', 'Индекс'],
];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY_VALUES);

  const isLastStep = step === STEPS.length - 1;

  const setField =
    (field: keyof RegistrationValues) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const { value } = event.target;
      setValues((prev) => ({ ...prev, [field]: value }));
    };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(values);
      return;
    }
    setStep((prev) => prev + 1);
  };

  return (
    <Card as="form" onSubmit={handleSubmit}>
      <Stack direction="vertical" gap="var(--jx-space-lg)">
        <Stepper activeStep={step} steps={STEPS as unknown as string[]} />

        {step === 0 && (
          <Stack direction="vertical" gap="var(--jx-space-md)">
            <Input
              label="Имя"
              name="name"
              value={values.name}
              onChange={setField('name')}
              autoComplete="name"
            />
            <Input
              label="E-mail"
              name="email"
              type="email"
              value={values.email}
              onChange={setField('email')}
              autoComplete="email"
            />
            <Input
              label="Телефон"
              name="phone"
              type="tel"
              value={values.phone}
              onChange={setField('phone')}
              autoComplete="tel"
            />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="vertical" gap="var(--jx-space-md)">
            <Input
              label="Страна"
              name="country"
              value={values.country}
              onChange={setField('country')}
              autoComplete="country-name"
            />
            <Input
              label="Город"
              name="city"
              value={values.city}
              onChange={setField('city')}
              autoComplete="address-level2"
            />
            <Input
              label="Улица, дом"
              name="street"
              value={values.street}
              onChange={setField('street')}
              autoComplete="street-address"
            />
            <Input
              label="Индекс"
              name="zip"
              value={values.zip}
              onChange={setField('zip')}
              autoComplete="postal-code"
            />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="vertical" gap="var(--jx-space-sm)">
            {REVIEW_ROWS.map(([field, label]) => (
              <Stack key={field} direction="horizontal" justify="space-between" gap="var(--jx-space-md)">
                <Text tone="muted">{label}</Text>
                <Text>{values[field] || '—'}</Text>
              </Stack>
            ))}
          </Stack>
        )}

        <Stack direction="horizontal" justify="space-between" gap="var(--jx-space-md)">
          <Button
            type="button"
            variant="secondary"
            disabled={step === 0}
            onClick={() => setStep((prev) => Math.max(0, prev - 1))}
          >
            Назад
          </Button>
          <Button type="submit" variant="primary">
            {isLastStep ? 'Отправить' : 'Дальше'}
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
}

